import React, { useState } from "react";
import axios from "axios";

export default function AuthPage({ onSuccess }) {
  const [isLogin, setIsLogin] = useState(true);
  const [message, setMessage] = useState("");

  const [form, setForm] = useState({
    name: "",
    email: "",
    password: "",
    cpassword: "",
  });

  const Validate = {
    name: (v) => {
      if (!v.trim()) return "Name is required";
      if (v.length < 5) return "Name must be at least 5 characters";
      return "";
    },
    email: (v) => {
      if (!v.trim()) return "Email is required";
      if (!/^[^\s@]+@[^\s@]+\.[^\s@]+$/.test(v))
        return "Invalid email format";
      return "";
    },
    password: (v) => {
      if (!v.trim()) return "Password is required";
      if (v.length < 6) return "Password must be at least 6 characters";
      return "";
    },
    cpassword: (p, cp) => {
      if (p !== cp) return "Passwords do not match";
      return "";
    },
  };

  const handleForm = (e) => {
    setForm({ ...form, [e.target.name]: e.target.value });
    setMessage("");
  };

  const handleSubmit = async (e) => {
    e.preventDefault();

    let error = "";

    if (isLogin) {
      error =
        Validate.email(form.email) ||
        Validate.password(form.password);
    } else {
      error =
        Validate.name(form.name) ||
        Validate.email(form.email) ||
        Validate.password(form.password) ||
        Validate.cpassword(form.password, form.cpassword);
    }

    if (error) {
      setMessage(error);
      return;
    }

    try {
      if (isLogin) {
        const res = await axios.post("http://localhost:5000/login", {
          email: form.email,
          password: form.password,
        });

        localStorage.setItem("isLogin", "true");
        localStorage.setItem("userId", res.data.userId);

        if (typeof onSuccess === "function") {
          onSuccess();
        }
      } else {
        const res = await axios.post("http://localhost:5000/signup", {
          name: form.name,
          email: form.email,
          password: form.password,
        });

        alert(res.data.message);
        setIsLogin(true);
      }
    } catch (err) {
      setMessage(err.response?.data?.message || "Server error");
    }
  };

  return (
    <div style={styles.container}>
      <div style={styles.card}>
        <h2 style={styles.title}>
          {isLogin ? "Welcome Back 👋" : "Create Account 🚀"}
        </h2>

        {message && <p style={{ color: "red" }}>{message}</p>}

        <form style={styles.form} onSubmit={handleSubmit}>
          {!isLogin && (
            <input
              type="text"
              name="name"
              placeholder="Full Name"
              value={form.name}
              onChange={handleForm}
              style={styles.input}
            />
          )}

          <input
            type="email"
            name="email"
            placeholder="Email"
            value={form.email}
            onChange={handleForm}
            style={styles.input}
          />

          <input
            type="password"
            name="password"
            placeholder="Password"
            value={form.password}
            onChange={handleForm}
            style={styles.input}
          />

          {!isLogin && (
            <input
              type="password"
              name="cpassword"
              placeholder="Confirm Password"
              value={form.cpassword}
              onChange={handleForm}
              style={styles.input}
            />
          )}

          <button type="submit" style={styles.button}>
            {isLogin ? "Log In" : "Sign Up"}
          </button>
        </form>

        <p style={styles.footer}>
          {isLogin ? (
            <>
              Don't have an account?{" "}
              <span style={styles.link} onClick={() => setIsLogin(false)}>
                Sign up
              </span>
            </>
          ) : (
            <>
              Already have an account?{" "}
              <span style={styles.link} onClick={() => setIsLogin(true)}>
                Log in
              </span>
            </>
          )}
        </p>
      </div>
    </div>
  );
}

const styles = {
  container: {
    height: "100%",
    display: "flex",
    alignItems: "center",
    justifyContent: "center",
  },
  card: {
    background: "rgba(255,255,255,0.1)",
    backdropFilter: "blur(12px)",
    padding: "2rem",
    maxWidth: "400px",
    width: "100%",
    color: "white",
    textAlign: "center",
  },
  title: {
    fontSize: "1.6rem",
    marginBottom: "1rem",
  },
  form: {
    display: "flex",
    flexDirection: "column",
    gap: "1rem",
  },
  input: {
    padding: "0.8rem",
    borderRadius: "8px",
    border: "none",
    background: "rgba(255,255,255,0.2)",
    color: "white",
  },
  button: {
    padding: "0.8rem",
    borderRadius: "8px",
    border: "none",
    background: "#38bdf8",
    color: "white",
    fontWeight: "bold",
    cursor: "pointer",
  },
  footer: {
    marginTop: "1rem",
  },
  link: {
    color: "#38bdf8",
    cursor: "pointer",
  },
};
